import{_ as o,C as s,o as r,c as t,a6 as n,E as i}from"./chunks/framework.CKIbuWFA.js";const h=JSON.parse('{"title":"Encontre preferências e controles de teclado","description":"","frontmatter":{"title":"Encontre preferências e controles de teclado","docId":"user.preferences.index","translationKey":"user.preferences.index","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6790ab7171a90bda1df882c0f88626a5875da68bf4f624968b0e54815842030f","translationRevision":"f109df7c60a73f42085174df738e19d5775ed761fd83df23a62b942b67ab744d","order":10},"headers":[],"relativePath":"pt/user/preferences/index.md","filePath":"pt/user/preferences/index.md","lastUpdated":1794611623000}'),d={name:"pt/user/preferences/index.md"};function c(l,e,p,u,f,m){const a=s("DemoFrame");return r(),t("div",null,[e[0]||(e[0]=n('<h1 id="find-preferences-and-keyboard-controls" tabindex="-1">Encontre preferências e controles de teclado <a class="header-anchor" href="#find-preferences-and-keyboard-controls" aria-label="Permalink to &quot;Encontre preferências e controles de teclado {#find-preferences-and-keyboard-controls}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Defina o idioma do aplicativo, encontre a área de configuração correta e use confortavelmente os controles de teclado disponíveis. Você precisa da janela de desktop aberta; acesso à rede só é necessário para o serviço configurado.</p><h2 id="find-the-relevant-setting" tabindex="-1">Encontre a configuração relevante <a class="header-anchor" href="#find-the-relevant-setting" aria-label="Permalink to &quot;Encontre a configuração relevante {#find-the-relevant-setting}&quot;">​</a></h2><ol><li>Abra <strong>Settings → General</strong> para escolher o idioma da interface. As opções atuais são inglês (<code>en</code>), espanhol (<code>es</code>), português (<code>pt</code>), francês (<code>fr</code>), chinês simplificado (<code>zh</code>) e japonês (<code>ja</code>). A seleção de idioma não altera identificadores de eventos do TikTok nem nomes da API de plugins.</li><li>Revise os controles do atualizador em General: canal, verificações automáticas, notificações e verificação manual quando compatível. Verificações automáticas são opcionais. A disponibilidade de atualizações assinadas depende da configuração de assinatura publicada da compilação.</li><li>Use <strong>Account</strong> para identidade do Cloud e seus diagnósticos. Use <strong>Collaboration</strong> para configurar o acesso do proprietário e <strong>Teams</strong> quando o host expuser essa capacidade.</li><li>Abra <strong>Plugins</strong> para preferências gerais de plugins e os painéis Settings/Connection de cada plugin. As credenciais de serviço de um plugin não pertencem às configurações de General.</li><li>Abra <strong>Automations → Variables</strong> para valores compartilhados de execução, <strong>Points</strong> para regras de ganho e <strong>Overlays</strong> para design de widgets. Essas áreas de configuração ficam intencionalmente junto dos recursos que afetam.</li></ol><p>A instalação automática é experimental e está desativada pelos controles de compilação do fluxo de lançamento atual. Uma preferência visível de verificação automática não promete instalação automática. Use o <a href="./../updates.html">processo de atualização</a> documentado e faça um <a href="./backups.html">backup</a> antes de mudar de versão.</p><h2 id="use-supported-keyboard-controls" tabindex="-1">Use os controles de teclado disponíveis <a class="header-anchor" href="#use-supported-keyboard-controls" aria-label="Permalink to &quot;Use os controles de teclado disponíveis {#use-supported-keyboard-controls}&quot;">​</a></h2><p>Use Tab e Shift+Tab para mover o foco entre controles comuns e Enter/Espaço para ativar botões focados. No inspetor de design de overlays, Ctrl/Meta+Z desfaz e Ctrl/Meta+Shift+Z ou Ctrl/Meta+Y refaz. Campos de texto mantêm seu próprio comportamento de desfazer. Esses são atalhos do editor, não atalhos globais de automação.</p><p>Escape fecha a gaveta de navegação estreita quando outro controle não o consumiu. Diálogos e editores podem tratar Escape por conta própria, incluindo um aviso de alterações não salvas. Automação por atalhos globais exige um plugin instalado compatível e as capacidades de backend informadas por ele.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, status e recuperação <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, status e recuperação {#expected-result-status-and-recovery}&quot;">​</a></h2><p>Essas configurações e interações locais por teclado estão disponíveis; não se afirma aceitação completa de acessibilidade/plataforma. Prefira botões rotulados, tamanhos de janela legíveis e rolagem do feed pausada quando o movimento distrair. Se uma configuração parecer ausente, confira a página responsável e a capacidade do host antes de redefinir dados. Consulte <a href="./troubleshooting.html">solução de problemas</a> para controles indisponíveis e <a href="./faq.html">perguntas frequentes</a> para distinções comuns.</p>',11)),i(a,{scenario:"settings",locale:"pt",title:"Demonstração: configurações"})])}const v=o(d,[["render",c]]);export{h as __pageData,v as default};
